protected void downgradeAnhangElements(Document doc) throws JaxenException {
        List nodes = XmlUtils.newXPath(
                "/io:openimmo/io:anbieter/io:anhang | " +
                        "/io:openimmo/io:anbieter/io:immobilie/io:anhaenge/io:anhang",
                doc).selectNodes(doc);
